<!DOCTYPE html>
<html>
<head>
<style>
  :root {
    --bg: var(--viz-panel, #0f172a);
    --text: var(--viz-text, #e2e8f0);
    --muted: var(--viz-muted, #94a3b8);
    --accent: var(--viz-accent, #6366f1);
    --border: var(--viz-border, #334155);
    --card: var(--viz-card, #1e293b);
  }
  html, body {
    margin: 0; padding: 0;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    height: 100%; overflow: hidden;
  }
  .wrap {
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    height: 100vh; padding: 16px; box-sizing: border-box;
    gap: 14px;
  }
  .scene {
    perspective: 900px;
    width: 220px; height: 220px;
    display: grid; place-items: center;
  }
  .cube {
    position: relative;
    width: 140px; height: 140px;
    transform-style: preserve-3d;
    animation: spin 9s linear infinite;
  }
  .face {
    position: absolute;
    inset: 0;
    display: grid; place-items: center;
    font-size: 30px; font-weight: 800; letter-spacing: 1px;
    border: 2px solid var(--border);
    background: var(--card);
    color: var(--text);
    backface-visibility: visible;
    box-shadow: inset 0 0 40px rgba(99,102,241,.15);
  }
  .face.front  { transform: translateZ(70px); background: linear-gradient(135deg, #6366f1, #8b5cf6); color:#fff; }
  .face.back   { transform: rotateY(180deg) translateZ(70px); }
  .face.right  { transform: rotateY(90deg) translateZ(70px); background: linear-gradient(135deg, #22d3ee, #6366f1); color:#fff; }
  .face.left   { transform: rotateY(-90deg) translateZ(70px); }
  .face.top    { transform: rotateX(90deg) translateZ(70px); background: linear-gradient(135deg, #f472b6, #8b5cf6); color:#fff; }
  .face.bottom { transform: rotateX(-90deg) translateZ(70px); }

  @keyframes spin {
    0%   { transform: rotateX(-20deg) rotateY(0deg); }
    100% { transform: rotateX(-20deg) rotateY(360deg); }
  }
  .caption { font-size: 13px; color: var(--muted); text-align: center; }
  .hint { font-size: 12px; color: var(--muted); opacity: .7; }

  /* Pause toggle */
  .controls { display: flex; gap: 8px; }
  button {
    background: var(--card); color: var(--text);
    border: 1px solid var(--border); border-radius: 8px;
    padding: 6px 12px; font-size: 12px; cursor: pointer;
    transition: border-color .15s, background .15s;
  }
  button:hover { border-color: var(--accent); }
  button.active { background: var(--accent); color: #fff; border-color: var(--accent); }
</style>
</head>
<body>
  <div class="wrap">
    <div class="scene">
      <div class="cube" id="cube">
        <div class="face front">G</div>
        <div class="face back">N</div>
        <div class="face right">U</div>
        <div class="face left">I</div>
        <div class="face top">★</div>
        <div class="face bottom">UI</div>
      </div>
    </div>
    <div class="caption">3D rotating logo</div>
    <div class="controls">
      <button id="pause">Pause</button>
      <button id="reset">Reset angle</button>
      <button id="copy">Copy name</button>
    </div>
    <div class="hint">CSS 3D transforms · no external assets</div>
  </div>
<script>
  const cube = document.getElementById('cube');
  const pauseBtn = document.getElementById('pause');
  let paused = false;
  pauseBtn.addEventListener('click', () => {
    paused = !paused;
    cube.style.animationPlayState = paused ? 'paused' : 'running';
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    pauseBtn.classList.toggle('active', paused);
  });
  document.getElementById('reset').addEventListener('click', () => {
    cube.style.animation = 'none';
    void cube.offsetWidth;
    cube.style.animation = '';
    cube.style.animationPlayState = paused ? 'paused' : 'running';
  });
  document.getElementById('copy').addEventListener('click', () => {
    window.GenUI && window.GenUI.copy('GENUI Logo');
  });
</script>
</body>
</html>
